# Meridian Credits

A Python standard-library JSON CLI for monthly loyalty-credit statements.

Run `python3 main.py` with one request on stdin. Check the starter with `python3 -m unittest discover -s tests`. Feature issues supply their interfaces and approved business agreements.

Run only introduced public suites with `python3 test_public.py --cases PATH`. Suite names and explicit requests identify their release; a change to the current agreement does not invalidate an explicit earlier-release suite.

`quote`, `total`, and `statement` accept an explicit `"release":"1.0"` or
`"release":"2.0"`; omitting `release` selects the current agreement, `"2.0"`.
For an itemized receipt, send `{"command":"statement","release":"1.0","lines":[...]}`.
The response contains `release`, `lines`, `credit_cents`, and `amount_due_cents`.
Each receipt line contains `line_id`, `credit_cents`, and `amount_due_cents`,
in input order. Release 1.0 floors each line's 10% credit to integer cents and
shares a 2,400-cent cap across all subscriptions of an account, allocating by
earliest `service_on`, then increasing `line_id`. Empty statements return an
empty line list and zero totals.

#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys


CURRENT_RELEASE = "2.0"


def line_credits(lines, release):
    percent, cap = {"1.0": (10, 2400), "2.0": (15, 3000)}[release]
    if release == "1.0":
        priority = lambda line: (line["service_on"], line["line_id"])
    else:
        priority = lambda line: (-line["charge_cents"], line["line_id"])
    group_credits = {}
    credits = {}
    # Sorting a copy assigns caps without changing the caller's line order.
    for line in sorted(lines, key=priority):
        group = (line["account_id"] if release == "1.0" else
                 (line["account_id"], line["subscription_id"]))
        used = group_credits.get(group, 0)
        credit = min(line["charge_cents"] * percent // 100, cap - used)
        credits[line["line_id"]] = credit
        group_credits[group] = used + credit
    return credits


def statement_credit(lines, release):
    return sum(line_credits(lines, release).values())


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if request.get("command") == "quote":
        line = request["line"]
        release = request.get("release", CURRENT_RELEASE)
        credit_cents = statement_credit([line], release)
        return {
            "release": release,
            "line_id": line["line_id"],
            "credit_cents": credit_cents,
            "amount_due_cents": line["charge_cents"] - credit_cents,
        }
    if request.get("command") in ("total", "statement"):
        release = request.get("release", CURRENT_RELEASE)
        charge_cents = sum(line["charge_cents"] for line in request["lines"])
        credits = line_credits(request["lines"], release)
        credit_cents = sum(credits.values())
        response = {
            "release": release,
            "credit_cents": credit_cents,
            "amount_due_cents": charge_cents - credit_cents,
        }
        if request["command"] == "statement":
            response["lines"] = [
                {
                    "line_id": line["line_id"],
                    "credit_cents": credits[line["line_id"]],
                    "amount_due_cents": (
                        line["charge_cents"] - credits[line["line_id"]]
                    ),
                }
                for line in request["lines"]
            ]
        return response
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")
"""Run one supplied public case file against the local application/artifacts."""
import argparse
import json
from pathlib import Path
import subprocess
import sys


def equal(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(equal(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(equal(a, b) for a, b in zip(left, right))
    return left == right


parser = argparse.ArgumentParser()
parser.add_argument("--cases", required=True)
args = parser.parse_args()
failed = 0
for case in json.loads(Path(args.cases).read_text()):
    try:
        if "artifact_json_path" in case:
            got = json.loads(Path(case["artifact_json_path"]).read_text())
        else:
            proc = subprocess.run([sys.executable, "main.py"], input=json.dumps(case["request"]),
                                  capture_output=True, text=True, check=True, timeout=5)
            got = json.loads(proc.stdout)
        ok = equal(got, case["expected"])
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        ok = False
        got = str(exc)
    print(("PASS " if ok else "FAIL ") + case["name"])
    if not ok:
        print(" expected:", case["expected"])
        print(" received:", got)
        failed += 1
raise SystemExit(bool(failed))
